  str_n7_mission_title_12 = "ST2 - Sombras",
  str_n7_mission_desc_2 = "Te diriges a Umbraton, la ciudad envuelta en sombras, después de recibir la carta.",
  str_n7_mission_desc_3 = "Después de reunirte con Bethel, llegas a la sede del gremio para prepararte para la entrega de los bienes de Caelestite.",
  str_n7_mission_desc_4 = "¿La sede está bajo ataque de Eclipsite? Que esta pasando...?",
  str_n7_mission_desc_5 = "Sin pistas, Luke te propone que pruebes suerte en el Crossroads Bar.",
  str_n7_mission_desc_6 = "La investigación está paralizada. Decides ir primero a la subasta clandestina con Luke.",
  str_n7_mission_desc_7 = "¿Rhein ha traicionado al Señor de las Sombras? ¡Tienes que encontrar a Bethel e informarle de inmediato!",
  str_n7_mission_desc_8 = "Betel también fue atacada, tal como temías. Parece que ahora se está gestando una rebelión en Umbraton...",
  str_n7_mission_desc_9 = "Al enterarse de que los otros gremios principales también fueron atacados, decide brindar apoyo de inmediato.",
  str_n7_mission_desc_10 = "Después de recibir más orientación, llegas a la sede de Steelfire Gang. Parece que los jefes de los principales gremios están retenidos aquí...",
  str_n7_mission_desc_11 = "Rhein y Maude probablemente estén atacando la presa en este mismo momento. ¡Ve a la Presa de las Cicatrices inmediatamente!",
  str_n7_mission_desc_long_1 = "Recibiste una carta de Umbraton invitándote a hacerte cargo de los bienes que dejaron los caelestitas.\nNaroxel también ha oído que un artículo único conocido como componente de la sala de simulación se subastará en el subsuelo de Umbraton...",
  str_n7_mission_desc_long_2 = "Esta es \"La ciudad envuelta en sombras\".\nTe has encontrado con el jefe del gremio, Bethel, pero los eclipses te atacan inesperadamente de camino a Umbraton.\nAfortunadamente, Luke, el comandante de un escuadrón de mercenarios local, apareció a tiempo y decidió acompañarte.",
  str_n7_mission_desc_long_3 = "Cuando llegas al gremio y te preparas para los procedimientos de entrega, ocurre otro ataque de Eclipsite.\nDado que esta es un área tan estrictamente protegida, ¿puede ser esto realmente una coincidencia?",
  str_n7_mission_desc_long_4 = "Da la casualidad de que Pittman también ha venido a Umbraton para investigar los misteriosos potenciadores y, por lo tanto, has ganado otro aliado.\nCon la esperanza de encontrar más pistas, Luke decide llevarte a algún lugar...",
  str_n7_mission_desc_long_5 = "Te encuentras con Rhein del Blue Lion Guild en Crossroads Bar, junto con otra persona misteriosa.\nConsiguen obstruir tu misión y, en lugar de encontrar pistas útiles, te encuentras bajo ataque una vez más.\nTambién parece que Bethel se ha ido con mucha prisa...",
  str_n7_mission_desc_long_6 = "Incapaz de continuar con su investigación, usted y Luke van a la casa de subastas para buscar los componentes de la sala de simulación, pero se encuentran nuevamente con Rhein y sus secuaces.\nEsta vez, toman el lugar rápidamente y sin piedad, y hacen un anuncio: Istvan está muerto.",
  str_n7_mission_desc_long_7 = "Después de salir de la subasta, te apresuras al gremio para encontrar a Bethel.\nEncuentras a Bethel en el cuartel general y te enfrentas a un asesinato. Afortunadamente, todo parece estar bajo control por ahora.",
  str_n7_mission_desc_long_8 = "Tu peor temor se ha hecho realidad: Rhein ha incitado la rebelión, y los hombres de Bethel también se encuentran entre los traidores.\nEn cuanto al Señor de las Sombras, todos se niegan a creer que está muerto.\nTu principal prioridad ahora es ayudar a los otros gremios bajo ataque y sofocar el caos...",
  str_n7_mission_desc_long_9 = "Al llegar al Lin Guild atacado, parece que alguien ya ha ayudado a resolver el problema.\nLuke también se da cuenta de una nueva pista y lo lleva a su próximo destino: la sede de Steelfire Gang.",
  str_n7_mission_desc_long_10 = "Llegas a la sede de Steelfire Gang y rescatas a los líderes del gremio que fueron secuestrados en la subasta.\nIstvan Gang finalmente hace una aparición inesperada y procede a mantener el orden.\n¡Tu próximo paso ahora es perseguir al perpetrador detrás de todo esto en Dam of Scars!",
  str_n7_mission_desc_long_11 = "Sus planes frustrados, Maude, enfurecida, se traga los potenciadores.\nBajo la imponente presencia del Señor de las Sombras, emerges victorioso y finalmente se revela la verdad.",
  str_n7_mission_desc_long_12 = "Muchas preguntas en torno a este asunto siguen sin respuesta... Pittman también decide continuar con su investigación.\nObtienes el componente de la sala de simulación por el que viniste, que puede ser de gran utilidad en el futuro...",
  str_n7_paper_1_1_title = "<size=40><color=#353330>¡Leones azules rugientes!\n¡Se anuncian las recompensas de Double Underground Arena!</color></size>",
  str_n7_paper_1_2_title = "<size=35>Una entrevista con \nel señor de las sombras</size>",
  str_n7_paper_1_3_title = "<size=30><color=#353330>Enciclopedia de eclipses #50\nLa última Caelestita</color></size>",
  str_n7_paper_1_4_title = "<size=30><color=#353330>Odd Jobs Temporada de Lluvias Oferta Jumbo</color></size>",
  str_n7_paper_1_5_title = "<size=30><color=#353330>¡Miller III toma el dinero y huye!\n¡Tienda prestigiosa a precio de ganga!</color></size>",
  str_n7_paper_2_1_title = "<size=40><color=#353330>¡Se acerca una tormenta!\nShine On, estrellas de la Arena Subterránea!</color></size>",
  str_n7_paper_2_2_title = "<size=40>Salón brumoso\nBanquete de la alta sociedad</size>",
  str_n7_paper_2_3_title = "<size=35><color=#353330>Gato perdido</color></size>",
  str_n7_paper_2_4_title = "<size=30><color=#353330>¡Nuevo servicio de decoración de Courier Union!</color></size>",
  str_n7_paper_2_5_title = "<size=30><color=#353330>El Lin Guild cierra temporalmente</color></size>",
  str_n7_paper_3_1_title = "<size=32><color=#353330>¡Caelestite triunfa en Arena subterránea por sorpresa!\n¿Está la salvación a la mano para una tienda centenaria?</color></size>",
  str_n7_paper_3_2_title = "<size=40>¿Gratis significa beneficio?\n¡Entrevista a Lady Sheol!</size>",
  str_n7_paper_3_3_title = "<size=30><color=#353330>Extraños eclipses avistados\nEn San Juan Confiamos</color></size>",
  str_n7_paper_3_4_title = "<size=30><color=#353330>¿Paz en Umbraton?\nSe rumorea que los titanes de la industria pondrán fin al conflicto</color></size>",
  str_n7_paper_3_5_title = "<size=35><color=#353330>Pandillas de chismes</color></size>",
  str_n7_paper_4_1_title = "<size=38><color=#353330>Noticia de última hora: ¡Blue Lions Bare Fangs!\n¡Rhein sospechoso de atacar la presa!</color></size>",
  str_n7_paper_4_2_title = [[
<size=35>Caballo oscuro
Supera las probabilidades de reclamar la victoria</size>]],
  str_n7_paper_4_3_title = "<size=35><color=#353330>Spearows gana nuevamente el premio de seguridad pública</color></size>",
  str_n7_paper_4_4_title = "<size=30><color=#353330>Subastas clandestinas de clase alta prohibidas\nCelebrado en secreto durante años como \"Salón\"</color></size>",
  str_n7_paper_4_5_title = "<size=30><color=#353330>Cadáver de Eclipsite arrojado a plena vista\nSospecha de participación en el Salón de la Justicia</color></size>",
  str_n7_paper_5_1_title = "<size=50><color=#353330>Todos saluden al poderoso Caelestite\n¡Todos saluden a las amistades!</color></size>",
  str_n7_paper_5_2_title = "<size=30>El cuartel general del gremio se intensifica\nLas subastas clandestinas volverán</size>",
  str_n7_paper_5_3_title = "<size=35><color=#353330>Reclutamiento de Mercenarios de la Llama Blanca</color></size>",
  str_n7_paper_5_4_title = "<size=30><color=#353330>¡Noticias de última hora! ¡Identificadas las calles fantasma errantes de Umbraton!</color></size>",
  str_n7_paper_5_5_title = "<size=30><color=#353330>Final de las caras del gremio del león azul\nFamilia Solus desaparecida</color></size>",
  str_n7_paper_1_1_content = "<size=35><color=#353330>Gracias a las importantes contribuciones financieras del Sr. Rhein del Blue Lion Guild, ahora una montaña de Nightium espera al ganador del próximo torneo Underground Arena. En respuesta al profuso agradecimiento de los organizadores, Rhein afirma que esta contribución fue simplemente el ingreso de un día para los Blue Lions, los legendarios gigantes comerciales de Umbraton.\nLa Arena Subterránea recibe su nombre no por el hecho de que se lleva a cabo bajo la superficie de la ciudad, sino por sus reglas, o más bien por el hecho de que no hay reglas. El vencedor puede dormir sobre un montón de oro, mientras que los perdedores... ya no tendrán que preocuparse por el futuro. Muchos de los luchadores menos valientes de la ciudad alguna vez fueron disuadidos. Sin embargo, con el enorme premio acumulado de este año, todos los luchadores se han convertido en contendientes de la noche a la mañana. La oficina de registro se ha visto abrumada con aspirantes todos los días. Algunos incluso han comenzado peleas callejeras para calentar para el evento.\nCon esta gran ocasión, el organizador agradeció una vez más a Rhein por su ayuda, mientras que el respetado Rhein dijo: \"No me agradezcas. Debería agradecerte la pasión que has mostrado por el Underground Arena. Me complace vean la emoción que generó el Underground Arena a medida que sobrellevamos estos días tristes. No importa si tomas el premio o no, espero que todos en Umbraton puedan olvidar sus problemas y disfrutar plenamente de la emoción del Underground Arena\".\nUno no puede dejar de elogiar a Rhein por su desinterés y amor por el Underground Arena. ¡Que el Gremio del León Azul prospere y siga apoyando el evento durante muchos años más!\n </color></size>",
  str_n7_paper_1_2_content = "<size=35><color=#353330>Recientemente se ha visto a Istvan deambulando por el desierto a las afueras de Umbraton, cada vez en un lugar diferente. Afortunadamente, nuestro reportero perfeccionó sus habilidades de rastreo en el ejército y fue coronado campeón de la maratón anual de evacuación del campo de batalla. Finalmente encontró al Señor de las Sombras en el valle del norte de Umbraton. ¡Resulta que Istvan es en realidad un hombre muy misterioso y encantador!\nNuestro reportero no escatimó esfuerzos para localizar a Istvan y pedirle su opinión sobre la inversión del Gremio del León Azul en la Arena Subterránea. El Señor de las Sombras respondió: \"Estaré observando\".\nComo todos sabemos, Istvan siempre se ha inclinado por prohibir este tipo de competiciones. Por lo tanto, muchos especuladores creen que la importante inversión del Blue Lion Guild en el Underground Arena es un desafío directo a la autoridad de Istvan. Según las noticias pasadas, Istvan está obligado a competir por el control de la Arena Subterránea. Sin embargo, después de escuchar la respuesta de Istvan, los comerciantes ahora creen que Shadowlord tiene asuntos más importantes en mente, lo que los lleva a comprar una gran cantidad de bonos del Blue Lion Guild.</color></size>",
  str_n7_paper_1_3_content = "<size=28><color=#353330>Hace diecisiete años, Eraveil fue destruido y solo quedaron con vida unos pocos Caelestitas, enemigos mortales de los Eclipsitas. Los caelestitas poseían poderosas habilidades psíquicas e incluso podían afectar los corazones de los demás. Algunos dicen que los caelestitas podrían incluso convertir a los aurorianos en eclipses.\nSe ha informado que el último Caelestite llegó a Umbraton con motivos aún desconocidos. Se recomienda a todos los residentes de Umbraton que presten especial atención a la seguridad personal en todo momento. Si ve el Caelestite, mantenga la distancia para evitar ser poseído psíquicamente o transformarse en un Eclipsite.</color></size>",
  str_n7_paper_1_4_content = "<size=28><color=#353330>Se acerca la temporada de lluvias. ¿Te has encontrado luchando para secar tu ropa? Además de los muchos otros servicios respetuosos de la ley que tiene para ofrecerle, Odd Jobs, la tienda que garantiza su satisfacción en todo momento, ¡ahora ha lanzado un nuevo servicio de secado Luminatics! Ya se trate de una camisa, un abrigo, pieles, bufandas tejidas o incluso un nuevo bolso de cuero de marca, Taki usará su Luminatic caliente y abundante para infundir sus posesiones con una fragancia única y hacer que se sequen en un abrir y cerrar de ojos. ¡Huélelos y llena tu corazón de sol, respira su fragante aroma y abraza la vitalidad del eterno verano!\nServicios gratuitos de recuperación de deuda por cincuenta prendas en un solo recibo. (Las cuadrillas de más de 100 miembros como deudor estarán sujetas a tarifas adicionales).</color></size>",
  str_n7_paper_1_5_content = "<size=28><color=#353330>Miller Guild, con su centenaria tienda Umbraton, es famosa por su servicio de reventa profesional y de alta calidad. Debido a la situación de seguridad pública cada vez más caótica en Umbraton recientemente, la mayoría de los delincuentes han estado utilizando medios no convencionales y no regulados para vender bienes robados. Algunos incluso han estado vendiendo sus bienes robados en la calle, iniciando guerras de precios que han resultado en una disminución significativa en la facturación de Miller Guild. Con el fin de salvar al gremio de la ruina, Miller III, el líder del gremio, rápidamente se volvió a apostar y, después de incurrir en enormes deudas de juego, parece haberse fugado y no se lo encuentra por ningún lado.\nAhora, Gambling Union ha confiado a este periódico el derecho de vender la licencia de reventa de bienes ilícitos de Miller Guild a un precio especial. Según fuentes confiables, las principales pandillas de Umbraton realizarán una operación conjunta pronto para reforzar la seguridad pública en Umbraton y arrestar a los comerciantes de productos ilegales. Se espera que esta operación resuelva el problema central de fallas comerciales de Miller Guild.</color></size>",
  str_n7_paper_2_1_content = "<size=35><color=#353330>El torneo Underground Arena ya está en marcha y la ferocidad de los contendientes ha comenzado a salir del cuadrilátero a las calles, ya que se han descubierto varios retadores populares en los callejones de la ciudad, neutralizados por sus compañeros competidores. Los feroces duelos de los últimos días han puesto en primer plano a varios luchadores con habilidades únicas, incluido el luchador cabeza de serie más emocionante y popular, Becker, que ascendió con éxito a la siguiente ronda. Pocos pueden olvidar el momento en que destruyó las manijas de metal de las puertas de la arena. Por supuesto, Becker es más que un showman carismático; hasta ahora, también ha destruido a todos sus oponentes. Así es, destruidos, no solo derrotados: todos los retadores lo suficientemente desafortunados como para haberse enfrentado a Becker ahora yacen en la misma habitación del Hospital General de Umbraton y ya no podrán competir en este torneo.\nDe acuerdo con el calendario del torneo, las preocupaciones ahora rodean al próximo oponente de Becker. Se rumorea que el recién llegado desconocido es el único sobreviviente de los Caelestites. ¡Aunque todos esperamos ver una batalla magnífica, también esperamos que el frágil cuerpo pueda soportar los sólidos puños de acero de Becker!\n¡Por supuesto, esta gran diferencia en la fuerza no significa que el resultado de esta batalla ya sea una conclusión inevitable! Según la investigación, los hábitos de vida convencionales pueden restringir seriamente el desarrollo del cuerpo, especialmente en términos de dieta. Por lo tanto, nos gustaría presentarles Power Punch Protein Powder, ¡desarrollado por Blue Lion Guild! ¡Toma tu dosis diaria para alcanzar nuevas alturas de condición física! El retador estrella Becker es el primer guerrero en probar este producto, y su efectividad ahora es obvia para cualquiera que haya estado siguiendo el torneo. ¡Contáctenos directamente para comprar Power Punch Protein Powder hoy!\n</color></size>",
  str_n7_paper_2_2_content = "<size=35><color=#353330>Las altas esferas de la sociedad de Umbraton y las celebridades de todos los círculos esperan una invitación a este raro y exclusivo salón y banquete con ansiosa anticipación. Este salón de la alta sociedad ha existido en Umbraton durante muchos años, a través de los tiempos difíciles y buenos. Desde sus inicios, ha servido a los placeres de la élite y las celebridades de todo tipo, con el objetivo de guiar a Umbraton hacia un futuro mejor y más próspero mediante el intercambio de ideas entre personas de diversos campos.\nLos organizadores mostrarán nuevas obras de arte en el próximo salón, incluidas Mountain Roots, The Fish's Breath, Paw Print y Empty Wisdom. Celebridades de Umbraton de todos los campos han sido invitadas a discutir sobre arte juntas, y los organizadores esperan sus valiosas evaluaciones.\nDeseamos a los organizadores y participantes del salón una noche productiva y agradecemos a los organizadores por su generoso patrocinio de este periódico.</color></size>",
  str_n7_paper_2_3_content = "<size=28><color=#353330>Mi gato ha desaparecido, ¡las palabras no pueden expresar lo importante que es para mí! ¿Podrías ayudarme? Si mi gato regresa sano y salvo, tendrás mi agradecimiento, ¡e incluso te daré cincuenta tazas de café como recompensa!\nAcerca de mi gato: es un pequeño gato mecánico negro, muy realista, pero con un cableado mecánico obvio visible en la sección dañada de su pata delantera izquierda. Tiene una cinta roja alrededor del cuello con una etiqueta de latón con su nombre.\nAdemás, sus ojos son de diferentes colores, ¡y es precioso!\nSi tiene alguna información, comuníquese con Connolly, propietario del Holiday Café. ¡Muchos gracias!</color></size>",
  str_n7_paper_2_4_content = "<size=28><color=#353330>The Courier Union, proveedor de servicios profesionales de renombre mundial, cree en brindar servicios de clase mundial a todas las personas amantes de la paz en Astra. ¡Y ahora, después de varios meses de preparación, Courier Union está lista para lanzar un nuevo servicio de decoración! Ya sea que viva en una habitación individual o en una mansión, el equipo de decoración de Courier Union puede brindarle una gama completa de servicios, desde diseño y adquisición hasta construcción y evaluación. ¡Prometemos que si el servicio no logra el efecto deseado, la redecoración es gratuita!\n¡Si solicita servicios de decoración a través de nuestro periódico, puede ahorrar 50 Nightium adicionales además de su 20% de descuento! Este evento está limitado solo a este mes, ¡así que asegúrese de hacer su pedido lo antes posible! Comuníquese con el representante de Umbraton, Eho, para obtener más detalles.</color></size>",
  str_n7_paper_2_5_content = "<size=28><color=#353330>Se han cerrado varios puntos de venta pertenecientes a The Lin Guild, con su hora de reapertura aún determinada.\nRecientemente, llevamos a cabo una investigación sobre el terreno de los rumores que rodeaban el cierre de varias tiendas pertenecientes a The Lin Guild. Ahora podemos informar que estas tiendas de hecho han sido cerradas. Estos cierres no se anunciaron con anticipación, lo que resultó en pérdidas significativas para muchos de sus clientes. Aquellos familiarizados con este asunto sospechan que la familia Lin está planeando una conspiración, pero se desconoce por completo exactamente cuándo estas tiendas reanudarán sus operaciones.</color></size>",
  str_n7_paper_3_1_content = "<size=35><color=#353330>\"El Caelestite es más como un pollo que un compañero de equipo\", gritó Becker antes del partido.\nSin embargo, uno nunca puede estar demasiado seguro en el fragor de la competencia. Bajo el mando de Caelestite, todo el equipo se movió como el viento, se coordinó perfectamente y atacó ferozmente. Si Becker no hubiera detenido el juego noqueando accidentalmente al juez en medio de la pelea, habría caído en la primera ronda de ataques.\nDespués de que se reanudó el combate, Becker esquivó antes del turno de ataque de Caelestite, pero de repente gritó de dolor y cayó al suelo, echando espuma por la boca. Luego comenzó a temblar por todas partes y pronto fue sacado del campo de batalla. Según el médico en el lugar, parece que el patrocinador le pidió a Becker que tomara Power Punch Protein Powder en medio de la competencia. Le provocó calambres abdominales y desencadenó un espasmo muscular abdominal inducido por el estrés, lo que lo obligó a tragarse la amargura de la derrota. Algunos también dicen que Caelestite vio que Becker tenía problemas para pelear y usó algunos trucos clandestinos para hacer que Becker tuviera calambres. Cualquiera que sea la verdad del asunto, esta emergencia causó pánico entre muchos concursantes que usan el mismo producto.\nNuestro reportero declaró que el silencio se apoderó de la arena después de la inesperada victoria de Caelestite. La única persona que comenzó a reír tan salvajemente como lo había hecho Becker antes de la pelea fue Miller III. Resulta que, en su desesperación, apostó todo lo que tenía en Caelestite. Las escandalosas probabilidades antes del partido le valieron una gran fortuna, y luego exclamó: \"¡El Miller Guild está listo para vender todos los bienes robados pendientes!\"\n </color></size>",
  str_n7_paper_3_2_content = "<size=35><color=#353330>Reportero: Hola, Señora Sheol. Cloudrover Guild recientemente comenzó una propaganda que dice \"paquete de regalo gratis\". Todo Umbraton está entusiasmado con eso, como el dinero crece en los árboles. ¿Puede hablarnos sobre la lógica detrás de este movimiento comercial?\nSeol: Por supuesto. En primer lugar, gracias por apoyar a Cloudrover Guild. La idea detrás de esto era mostrar nuestra gratitud. Es por eso que el gremio decidió proporcionar a todos estos paquetes de regalo.\nReportero: Muchos inversores creen que este movimiento de Cloudrover Guild generará pérdidas. Sin embargo, los resultados los han dejado boquiabiertos: ¡los ingresos del Cloudrover Guild han aumentado! ¿Puedes decirnos por qué?\nSheol: Hemos fortalecido la imagen pública del Cloudrover Guild. Como resultado, ¡actualizaremos aún más los paquetes de regalo a \"Paquetes de regalo—Plus\"! ¡Cada residente de Umbraton obtendrá uno gratis, sin condiciones adicionales!\nConclusión: ¡Gloria al gremio Cloudrover! Aunque están repartiendo paquetes de regalo, muchas personas se han inspirado para gastar aún más después de abrir los suyos. Un flujo interminable de personas ha estado inundando Cloudrover Guild para comprar más de sus productos. ¡Ahora es el momento de que los reporteros vayan a recoger su paquete de regalo!</color></size>",
  str_n7_paper_3_3_content = "<size=28><color=#353330>Ayer, un grupo de Eclipsitas mutados atacó repentinamente varios camiones. Estos eclipses escondidos en las sombras exhibían formas extrañas y un poder infinito. Pueden haber sido resultados experimentales de algún científico loco desconocido de Lumopolis. ¡Nuestro Umbraton ahora está bajo amenazas duales de Lumopolis y Eclipsites mejorados!\nDurante el ataque, alguien roció sabiamente el polvo erradicador de Eclipsite de St. John sobre los Eclipsites. Los Eclipsites inmediatamente se cubrieron la cara y gritaron mientras huían. Todos los presentes sobrevivieron.\nEl polvo para erradicar el eclipse de St. John's se elabora a través de 88 procesos elaborados y es un medicamento esencial para cualquier persona, tanto en casa como fuera, para combatir los males.</color></size>",
  str_n7_paper_3_4_content = "<size=28><color=#353330>Según los últimos informes internos, Rhein, el líder del Blue Lion Guild, uno de los más prósperos de la ciudad en los últimos años, parece estar contactando activamente a Istvan en privado, esperando la coexistencia pacífica de las dos partes en el futuro. Istvan también parece haber respondido de buena voluntad.\nAunque la lucha por el poder entre el Gremio del León Azul y el Cuartel General del Gremio liderado por Istvan ha promovido la prosperidad y el desarrollo en Umbraton, también ha causado objetivamente muchos problemas sociales. Algunos críticos creen que este es un paso importante para establecer una verdadera paz en Umbraton, que simboliza la reconciliación entre las nuevas y viejas fuerzas del pueblo.\nAlgunos también creen que esto es solo una cortina de humo para ambos lados. Ahora estamos siendo testigos de la calma antes de la tormenta como un brebaje de conspiración más grande.</color></size>",
  str_n7_paper_3_5_content = "<size=28><color=#353330>Según fuentes fidedignas, la familia Solus ha reclutado recientemente tropas en secreto para formar un equipo profesional experto en operaciones encubiertas e incluso ha reclutado a Mund, el Rey del Sigilo. Abundan los rumores de que la misteriosa desaparición de muchos dignatarios de Umbraton y Lumopolis está indisolublemente ligada a Mund. En la actualidad, varios miembros sospechosos de tener un conflicto de intereses con organizaciones comunitarias han desaparecido.\nEl equipo profesional formado por la familia Solus pronto podría cambiar el orden actual de Umbraton.</color></size>",
  str_n7_paper_4_1_content = "<size=35><color=#353330>La presa de las cicatrices ha sido saboteada. Esta impactante noticia se ha extendido por todo Umbraton y ha causado una gran conmoción en la ciudad. Sin embargo, podemos informar con confianza que el culpable detrás de la destrucción de la presa no fue otro que el líder del Blue Lion Guild, Rhein, quien ya ha sido llevado ante la justicia por el fiel protector de Umbraton, Istvan.\nCuando la inundación subsiguiente se precipitó hacia Umbraton, Istvan una vez más se mantuvo firme contra la marea. Ordenó a sus mercenarios drenar y redirigir el agua de la región y ayudar a los residentes a escapar de la zona de peligro. Además, Istvan coordinó sus fuerzas con Cloudrover Guild para rescatar a los heridos. Luego envió a su pandilla a acabar con Solus y sus seguidores, quienes planeaban aprovechar esta oportunidad para destruir Umbraton. Gracias al sabio liderazgo de Istvan, Umbraton sobrevivió a esta crisis con pérdidas mínimas. Agradezcamos una vez más a Istvan por su dedicación desinteresada a Umbraton.\nQue Istvan continúe salvaguardando Umbraton, ahora y siempre fielmente.\n</color></size>",
  str_n7_paper_4_2_content = "<size=35><color=#353330>Es natural apoyar al caballo oscuro. Caelestite ha ganado todas las batallas durante varios días consecutivos. Ahora, todos los ojos están puestos en el último Caelestite que avanza en el torneo, convirtiéndose en uno de los jugadores más populares en el campo de batalla. Los seguidores, que colectivamente se llaman a sí mismos \"Lovegators\", ahora han crecido considerablemente.\nPero centrémonos ahora en los eventos que ocurren fuera de la arena. Desafortunadamente, los seguidores de Caelestite han estado causando disturbios en las calles, participando en frecuentes enfrentamientos con los seguidores de otros jugadores durante los últimos dos días. Anoche, incluso iniciaron violencia entre la multitud que presenciaba el evento, provocando un caos generalizado. Según los informes, Caelestite personalmente no estaba al tanto de estos eventos. Sin embargo, todavía no es difícil ver que la aparición del caballo oscuro de Caelestite ha intensificado las diferencias inherentes que existen entre los seguidores. La mayoría de los seguidores de Caelestite son jóvenes ávidos de cambio, mientras que los seguidores que se enfrentan a ellos pertenecen a la vieja escuela, ansiosos por volver a ser el campeón reinante de la arena.\nDado que la fricción entre los dos lados existe desde hace algún tiempo, la aparición de Caelestite solo ha agregado combustible al fuego, lo que resulta en un infierno que se prepara para alcanzar un punto álgido. ¿Hasta dónde puede llegar este caballo oscuro? Vamos a esperar y ver.</color></size>",
  str_n7_paper_4_3_content = "<size=28><color=#353330>El territorio controlado por los feroces Spearows ha sido galardonado con el Premio de Seguridad Pública de Umbraton una vez más. Cuando nuestro reportero entrevistó a Dayna y Robyn para preguntarles cómo los Spearow se las han arreglado para detener a docenas de pandilleros callejeros cada semana de manera consistente, los jóvenes y modestos líderes dijeron lo siguiente: \"Estos tontos en la calle siempre están tratando de lastimar a Robyn. .. ¡Oye! ¡Tú de ahí! ¡¿Qué estás mirando?!\nAgradezcamos a Dayna y Robyn por su destacada contribución a la seguridad de la comunidad.</color></size>",
  str_n7_paper_4_4_content = "<size=28><color=#353330>Se informa que Rhein había estado realizando subastas ilegales en secreto con el pretexto de celebrar salones frecuentes. Nuestros reporteros han confirmado que todas las personas de interés relacionadas han sido arrestadas.\nEste periódico declara por la presente que no tuvimos conocimiento de los actos ilegales perpetrados por el Blue Lion Guild. Todos los informes relacionados publicados para el salón en el pasado fueron honestos y solo con fines comerciales. En el futuro, todo el contenido será monitoreado y verificado de manera más estricta para evitar la difusión de información que pueda tener un efecto adverso en la sociedad de Umbraton.</color></size>",
  str_n7_paper_4_5_content = "<size=28><color=#353330>Se ha encontrado una gran cantidad de cuerpos mejorados de Eclipsite en el callejón al lado del Cornwall Cafe en Cross Street. Una mesera del café nos dijo que escuchó un ruido extraño al cerrar anoche. Desde el escaparate, vio a un hombre musculoso con un uniforme de Lumo Hall of Justice arrojando Eclipsites moribundos al callejón uno a la vez.\nEstos cuerpos ahora han comenzado a descomponerse, creando un olor acre en el área circundante. Se insta al hombre responsable a comunicarse con la Oficina de Saneamiento de Umbraton Street lo antes posible para pagar las tarifas de eliminación correspondientes y las multas relacionadas. De lo contrario, Umbraton no tendrá más remedio que presentar cargos contra el Salón de Justicia de Lumo por contaminar el medio ambiente.</color></size>",
  str_n7_paper_5_1_content = "<size=35><color=#353330>Acabamos de presenciar un torneo ferozmente emocionante, gracias al caballo oscuro, o deberíamos decir, ¡gracias a la todopoderosa Caelestite! ¡Gracias por brindarnos un espectáculo tan increíble!\nAl observar los juegos anteriores, comprar información en el mercado negro y escuchar a escondidas, muchos fuertes contendientes por el campeonato se enteraron de las tácticas de Caelestite. Por lo tanto, cuando se enfrentaron a los ataques mordaces del equipo de Caelestite, estos contendientes no adoptaron una estrategia conservadora y clara, sino que eligieron atacar de frente. ¡Después de estos ataques salvajes y desesperados, pagaron el precio más alto por su temeridad y contemplarán su decisión en el hospital local!\n¡Sin fallar las esperanzas de los Lovegators! ¡Sin dejar ninguna oportunidad a los oponentes! ¡Viva la Caelestita! Enfrentando las estrategias específicas y los esquemas insidiosos de los oponentes, no hubo quejas sobre sus travesuras ante el árbitro. Y nuestro Caelestita demostró un talento majestuoso para las tácticas y el liderazgo heredado de los grandes comandantes Caelestitas que alguna vez estuvieron presentes en Lumopolis, Illumina, Eraveil, Umbraton y Northland. ¡Aprovechando el momento para reclamar la victoria! ¡La gloriosa tradición de los Caelestitas!\nVerdaderamente uno en un millón, nuestro Caelestite posee el poder de percibir oportunidades para atacar que la mayoría de la gente común nunca podría aprovechar en una vida de batallas, ¡oportunidades que se presentan una vez cada mil años! Ahora, Caelestite no está luchando solo, ¡glorioso Navegante, la victoria es tuya!\n¡Con el poder de acabar con los enemigos en un golpe decisivo, todo lo que se necesita es un comando! ¡Un ataque devastador! ¡Dejar a los enemigos sin la más mínima oportunidad de reaccionar! ¡Con todos en la multitud dando testimonio! El Caelestite reclamó la victoria, no solo personal, sino también para los compañeros Caelestites, el equipo, el Underground Arena, Istvan, Umbraton y todos los que aman la emoción del combate en todo el mundo. ¡Viva la Caelestita!\n* Nos gustaría aprovechar esta oportunidad para disculparnos con todos los lectores. Hacía mucho tiempo que no veíamos un torneo tan emocionante. Como el reportero que presenció la batalla final se desmayó de la emoción después de escribir el informe en vivo anterior, el editor en jefe se ha encargado de continuar escribiendo este artículo.\nDespués de la victoria de Caelestite, Istvan le entregó a nuestro ganador un cinturón, que representa la máxima supremacía en la Arena subterránea, ¡lo que aseguró un lugar en el salón de la fama para Caelestite! Cuando el cinturón se levantó en alto, la audiencia estalló en una estridente ronda de aplausos. Además, los vítores resonaron por toda la arena durante lo que pareció una eternidad.\n¡Todopoderoso campeón de Caelestite, siempre tendrás un lugar en el corazón de todos y cada uno de los habitantes de Umbraton!\n</color></size>",
  str_n7_paper_5_2_content = "<size=35><color=#353330>Las subastas clandestinas fueron suspendidas debido a la reciente rebelión. Ahora ha sido proscrito debido a su inextricable relación con Rhein. Después de enterarse de esta desafortunada noticia, tanto los compradores como los vendedores clamaron con indignación que ya no tendrían la oportunidad de adquirir los raros artículos de subasta en oferta ni obtener beneficios financieros de estas subastas, un doble golpe para todos los involucrados.\nEn medio del pesimismo que rodeaba la situación, Bethel propuso que el Cuartel General del Gremio de Umbratón reviviera fielmente estas subastas clandestinas. Sí, así es, ¡un avivamiento fiel! Ella prometió continuar organizando las subastas, brindando un nuevo lugar, publicidad y seguridad, lo que llevaría a los desalentados compradores y vendedores de Umbraton a ver finalmente la luz de la esperanza.\nDespués de esto, bajo la supervisión del Cuartel General del Gremio, se llevó a cabo la primera subasta en Umbraton Square. Cuando todos escucharon el eco del martillo al caer, el evento fue reconocido oficialmente como una subasta en la superficie. Bethel también anunció que, a partir de ese día, la subasta de la superficie estaría abierta a todos. Todo el mundo puede unirse, siempre que envíe una solicitud a la sede del gremio y reciba la autorización, ¡sin condiciones adicionales! Los involucrados en las subastas originales se quedaron llorando lágrimas de alegría al escuchar la noticia. Aplaudieron la decisión de Bethel y anunciaron que estarían orgullosos de participar en las nuevas subastas de superficie.\n¡Viva la subasta aérea! ¡Viva el libre comercio! ¡Viva Betel!</color></size>",
  str_n7_paper_5_3_content = "<size=28><color=#353330>Credibilidad ilimitada! Los poderes de batalla, la habilidad y la experiencia son todas virtudes que se pueden cultivar, pero ninguna virtud es más difícil de refinar que la credibilidad. En este escuadrón de mercenarios, puedes confiar con seguridad en tus aliados y hacer que te traten de la misma manera.</color></size>",
  str_n7_paper_5_4_content = "<size=28><color=#353330>Residentes de Cross Street, ¿han escuchado risas extrañas haciendo eco en las calles a altas horas de la noche? La fuente de esta risa fue una sombra oscura recientemente vista al acecho al final de la calle. ¿Era esta sombra una aberración de la naturaleza auroriana? ¿O la encarnación de nuestra moralidad colectiva en declive? Ahora resolveremos este acertijo, exclusivamente para ti: esta sombra que atormentaba a Umbraton en la oscuridad de la noche era, de hecho, nada menos que Miller III.\nMiller III, que hizo una apuesta extremadamente grande a la victoria de Caelestite, perdió recientemente su inversión debido al colapso del Blue Lion Guild. Aparentemente, también recibió un duro golpe en su ego y recurrió a Umbraton errante por la noche como un espectro inquieto.\nCuando nuestro reportero finalmente lo acorraló y le preguntó cómo se sentía acerca de la victoria de Caelestite, de repente gritó y salió corriendo. Todo lo que nuestro reportero logró encontrar de él fue un zapato sin cordones a la orilla del río. Miller III, el heredero del gremio centenario, ahora está desaparecido, dado por muerto.\nLos cazadores de sueños como él aparecen en Umbraton todos los días. Mientras puedas adaptarte a las reglas no escritas de Umbraton, este puede ser un lugar maravilloso. Si no lo haces, te espera un destino desafortunado. Ah, el hermoso y misterioso Umbraton, un lugar de esperanzas, deseos y sueños sin fin.</color></size>",
  str_n7_paper_5_5_content = "<size=28><color=#353330>Alguna vez se consideró respetable que los residentes de Umbraton obtuvieran un puesto en el Gremio del León Azul. Ahora el Gremio del León Azul se ha convertido en el objeto del desprecio de la ciudad. Sus miembros han abandonado sus broches que alguna vez fueron orgullosos y desertaron para unirse a otros gremios con la esperanza de sobrevivir en Umbraton.\nLa familia Solus, los instigadores del reciente tumulto, han desaparecido y lo más probable es que hayan huido de Umbraton. Fuentes anónimas ahora ofrecen un alto precio por información sobre la familia Solus. Si conoce su paradero o estado actual, vivo o muerto, informe a este periódico de inmediato.</color></size>",
  str_n7_integral_contrast = "Honor actual/Honor disponible",
  str_n7_recommend_lv = "Nivel Aurorian Promedio Recomendado",
  str_n7_activity_lock = "Bloqueado",
